// Generates the complete Acme Corp mock documents from the content specs in ./mock-documents/content.
//
//   node scripts/generate-mock-documents.mjs
//
// For each spec this writes:
//   Box_Upload_Folder/<dir>/<file>             real .docx / .pdf / .xlsx
//   synthetic_demo_content/<file>.txt          plain-text export of the same content
//   src/data/syntheticDocumentContent.ts       text + size used by the in-app Box preview
//
// To push the regenerated files into Box as new versions (file IDs are preserved):
//   node scripts/convert-box-sources.mjs
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { renderDocx, renderPdf, renderXlsx, renderText } from './mock-documents/lib.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const contentDir = path.join(__dirname, 'mock-documents', 'content');
const boxRoot = path.join(root, 'Box_Upload_Folder');
const textRoot = path.join(root, 'synthetic_demo_content');
const tsOut = path.join(root, 'src', 'data', 'syntheticDocumentContent.ts');

const RENDER = { docx: renderDocx, pdf: renderPdf, xlsx: renderXlsx };

const formatSize = (bytes) => (bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1048576).toFixed(1)} MB`);

const files = fs.readdirSync(contentDir).filter((f) => f.endsWith('.mjs')).sort();
const inApp = {};
let total = 0;

for (const f of files) {
  const { default: def } = await import(path.join(contentDir, f));
  const buffer = await RENDER[def.kind](def.spec);
  const text = renderText(def.spec);

  const outDir = path.join(boxRoot, def.dir);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, def.file), buffer);

  if (def.inApp) {
    fs.mkdirSync(textRoot, { recursive: true });
    fs.writeFileSync(path.join(textRoot, `${def.file}.txt`), text);
    inApp[def.file] = { size: formatSize(buffer.length), text };
  }
  total++;
  console.log(`built  ${path.join(def.dir, def.file).padEnd(78)} ${String(buffer.length).padStart(7)} bytes  ${text.split(/\s+/).length} words`);
}

const header = `// GENERATED by scripts/generate-mock-documents.mjs - do not edit by hand.
// Edit the content specs in scripts/mock-documents/content/ and re-run the generator.
`;
const body = Object.entries(inApp)
  .map(([name, v]) => `  ${JSON.stringify(name)}: {\n    size: ${JSON.stringify(v.size)},\n    text: ${JSON.stringify(v.text)},\n  },`)
  .join('\n');
fs.writeFileSync(
  tsOut,
  `${header}\nexport const MOCK_DOCUMENT_CONTENT: Record<string, { size: string; text: string }> = {\n${body}\n};\n`,
);
console.log(`\nGenerated ${total} files; wrote ${path.relative(root, tsOut)}`);
